#!/usr/bin/env node
// C4 census-completeness check for the chord-pair census at the q=w+1 boundary.
//
// At q=w+1 a >=q-point circle could in principle have a single 2-point row
// (2+1+1+1+... row distribution), which the chord-pair decomposition (two
// 2-point rows required) would miss. This script settles completeness at a
// given (w,m,q) by comparing
//   (a) the surgery.js buildCensus curve set (chord-pair, mechanically
//       extracted verbatim from the experiment's surgery.js - see
//       census_extract.js, generated by sed of the exact source lines), and
//   (b) an independent all-triples enumeration: every C(w*m,3) cell triple
//       determines a line (collinear) or a circle (otherwise); every curve
//       with >=q in-board points is therefore found by construction.
//       Canonical integer forms: lines ax+by=c (content-1, sign-fixed);
//       circles A(x^2+y^2)+Bx+Cy+D=0 with A>0, content-1 (exact integer
//       arithmetic, no floating point).
// PASS = the two curve sets (as sorted in-board point lists) are identical.
//
// Usage: node c4_census_check.js <w> <m> <q>

"use strict";
const { buildCensus } = require("./census_extract.js");
const W = Number(process.argv[2]), M = Number(process.argv[3]), Q = Number(process.argv[4]);
const N = W * M;
const px = (i) => i % M, py = (i) => Math.floor(i / M);

function gcdN(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { const t = a % b; a = b; b = t; } return a || 1; }

// ---- independent all-triples census ----
function allTriplesCensus() {
  const curves = new Map(); // key -> {kind, coef, pts:Set}
  const collinear = (x1,y1,x2,y2,x3,y3) => (x2-x1)*(y3-y1) - (y2-y1)*(x3-x1) === 0;
  for (let a = 0; a < N; a++) for (let b = a+1; b < N; b++) for (let c = b+1; c < N; c++) {
    const x1=px(a),y1=py(a),x2=px(b),y2=py(b),x3=px(c),y3=py(c);
    if (collinear(x1,y1,x2,y2,x3,y3)) {
      // line through the triple: normalize ax+by=c
      let A = y2-y1, B = x1-x2, C = A*x1 + B*y1; // A x + B y = C
      const g = gcdN(gcdN(Math.abs(A),Math.abs(B)),Math.abs(C)); A/=g; B/=g; C/=g;
      if (A < 0 || (A === 0 && B < 0)) { A=-A; B=-B; C=-C; }
      const key = 'L:'+A+','+B+','+C;
      if (!curves.has(key)) curves.set(key, { kind:'line', coef:[A,B,C] });
    } else {
      // circle through the triple, exact rational center via 2x2 solve
      // 2(x2-x1) cx + 2(y2-y1) cy = x2^2+y2^2-x1^2-y1^2 etc.
      const A1 = 2*(x2-x1), B1 = 2*(y2-y1), C1 = x2*x2+y2*y2-x1*x1-y1*y1;
      const A2 = 2*(x3-x1), B2 = 2*(y3-y1), C2 = x3*x3+y3*y3-x1*x1-y1*y1;
      const det = A1*B2 - A2*B1;
      if (det === 0) continue; // degenerate (cannot happen for non-collinear)
      const n1 = C1*B2 - C2*B1, n2 = A1*C2 - A2*C1; // cx=n1/det, cy=n2/det
      // scale by d=det: A(x^2+y^2)+Bx+Cy+D=0 with A=det^2, B=-2 n1 det, C=-2 n2 det
      const K = (det*x1 - n1)*(det*x1 - n1) + (det*y1 - n2)*(det*y1 - n2); // = det^2 * r^2
      let A = det*det, B = -2*n1*det, C = -2*n2*det, D = n1*n1 + n2*n2 - K;
      const g = gcdN(gcdN(gcdN(Math.abs(A),Math.abs(B)),Math.abs(C)),Math.abs(D));
      A/=g; B/=g; C/=g; D/=g;
      if (A < 0) { A=-A; B=-B; C=-C; D=-D; }
      const key = 'C:'+A+','+B+','+C+','+D;
      if (!curves.has(key)) curves.set(key, { kind:'circle', coef:[A,B,C,D] });
    }
  }
  // count in-board points, keep >= Q
  const keep = [];
  for (const { kind, coef } of curves.values()) {
    const pts = [];
    for (let i = 0; i < N; i++) {
      const x = px(i), y = py(i);
      let on;
      if (kind === 'line') on = coef[0]*x + coef[1]*y === coef[2];
      else on = coef[0]*(x*x+y*y) + coef[1]*x + coef[2]*y + coef[3] === 0;
      if (on) pts.push(i);
    }
    if (pts.length >= Q) keep.push(Int32Array.from(pts).sort());
  }
  return keep;
}

// ---- compare ----
const t0 = Date.now();
const ref = buildCensus(W, M, Q);
const refKeys = new Set(ref.curves.map(cv => Array.from(cv).sort((a,b)=>a-b).join('|')));
const ind = allTriplesCensus();
const indKeys = new Set(ind.map(cv => Array.from(cv).join('|')));
let onlyRef = [], onlyInd = [];
for (const k of refKeys) if (!indKeys.has(k)) onlyRef.push(k);
for (const k of indKeys) if (!refKeys.has(k)) onlyInd.push(k);
const nRows = ref.curves.filter(cv => { const xs = new Set(); for (const p of cv) xs.add(py(p)); return xs.size === 1; }).length;
const result = {
  w: W, m: M, q: Q,
  chordPair: { curves: ref.nC, circles: ref.nCirc, rows: nRows },
  allTriples: { curves: ind.length },
  onlyInChordPair: onlyRef.length, onlyInAllTriples: onlyInd.length,
  pass: onlyRef.length === 0 && onlyInd.length === 0 && ref.nC === ind.length,
  seconds: +((Date.now()-t0)/1000).toFixed(1),
};
console.log(JSON.stringify(result));
if (!result.pass) { console.log('examples onlyInChordPair:', onlyRef.slice(0,3)); console.log('examples onlyInAllTriples:', onlyInd.slice(0,3)); process.exit(1); }
